use std::collections::HashMap;
use std::str::Chars;

/// Checks if brackets in a UTF-8 string are balanced.
///
/// Supports (), [], and {}.
///
/// Time complexity: O(n), where n is the length of the string.
/// Space complexity: O(n) in the worst case (stack usage proportional to string length).
pub fn is_balanced(s: &str) -> bool {
    let mut stack: Vec<char> = vec[];

    // Map closing brackets to their corresponding opening brackets
    let bracket_map: HashMap<char, char> = [
        (')', '('),
        (']', '['),
        ('}', '{'),
    ]
    .iter()
    .cloned()
    .collect();

    for c in s.chars() {
        match c {
            '(' | '[' | '{' => {
                stack.push(c);
            }
            ')' | ']' | '}' => {
                if stack.is_empty() {
                    return false;
                }
                let top = stack.pop().unwrap();
                if top != bracket_map[&c] {
                    return false;
                }
            }
            _ => {} // Ignore non-bracket characters
        }
    }

    stack.is_empty()
}
```

### Explanation

- **Algorithm**: We use a stack to keep track of opening brackets. As we iterate through the string:
  - If we encounter an opening bracket (`(`, `[`, `{`), we push it onto the stack.
  - If we encounter a closing bracket (`)`, `]`, `}`), we check if the stack is empty (unbalanced) or if the top of the stack matches the corresponding opening bracket. If not, the string is unbalanced.
